/*
 * Service worker of the installable application (generated by PwaController, version {{ $version }}).
 * Scope: {{ $scope }} — the website is never handled here.
 * - Static files (styles, scripts, fonts, icons): from the network (always the deployed version),
 *   kept in the cache only to start without connection.
 * - Pages: always from the network (they hold guests and amounts: never cached); without
 *   connection, the « Pas de connexion » page.
 * - Anything else (forms, feeds, other sites): untouched.
 */
const CACHE = 'hotel-app-{{ $version }}';
const OFFLINE_URL = @json($offlineUrl);
const PRECACHE = @json($precache);

self.addEventListener('install', (event) => {
    event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(PRECACHE)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', (event) => {
    event.waitUntil(
        caches.keys()
            .then((keys) => Promise.all(keys.filter((key) => key.startsWith('hotel-app-') && key !== CACHE).map((key) => caches.delete(key))))
            .then(() => self.clients.claim())
    );
});

const isStatic = (url) => url.origin === self.location.origin
    && /^\/(app|vendor)\//.test(url.pathname)
    && !url.pathname.startsWith('/app/images/uploads');

self.addEventListener('fetch', (event) => {
    const request = event.request;
    if (request.method !== 'GET') {
        return;
    }
    const url = new URL(request.url);

    if (request.mode === 'navigate') {
        event.respondWith(fetch(request).catch(() => caches.match(OFFLINE_URL)));
        return;
    }

    if (isStatic(url)) {
        event.respondWith(
            fetch(request)
                .then((response) => {
                    if (response.ok) {
                        const copy = response.clone();
                        caches.open(CACHE).then((cache) => cache.put(request, copy));
                    }
                    return response;
                })
                .catch(() => caches.match(request))
        );
    }
});
